#include "velocity_controller.hpp"
#include <algorithm>
namespace mobile_robot { void VelocityController::configure(const float kp,const float ki,const float kd,const float feed_forward,const float integrator_limit){kp_=kp;ki_=ki;kd_=kd;feed_forward_=feed_forward;integrator_limit_=integrator_limit;reset();} void VelocityController::reset(){integrator_=0.0F;previous_error_=0.0F;first_update_=true;} float VelocityController::update(const float target,const float measured,const float dt_seconds){if(dt_seconds<=0.0F)return 0.0F;const float error=target-measured;integrator_+=error*dt_seconds;integrator_=std::clamp(integrator_,-integrator_limit_,integrator_limit_);float derivative=0.0F;if(!first_update_)derivative=(error-previous_error_)/dt_seconds;previous_error_=error;first_update_=false;return std::clamp(feed_forward_*target+kp_*error+ki_*integrator_+kd_*derivative,-1.0F,1.0F);} }
